def pair(data, key):
    """(bn, en) from {"key": {"bn", "en"}}, {"key_bn", "key_en"} or a plain Bengali string."""
    value = data.get(key)
    if isinstance(value, dict):
        return value.get("bn") or "", value.get("en") or ""
    return data.get(f"{key}_bn") or value or "", data.get(f"{key}_en") or ""


